{
  "rules": [
    {
      "id": "check_currency_allowed",
      "description": "Ensure that the currency values are either 'USD' or 'EUR'.",
      "gx_code": "gx.expectations.ExpectColumnValuesToBeInSet(column='currency', value_set=['USD', 'EUR'])",
      "evidence_references": ["SOURCE_CONTEXT.schema"]
    },
    {
      "id": "check_balanced_journals",
      "description": "Ensure that the total debits equal the total credits for each journal.",
      "gx_code": "gx.expectations.ExpectMulticolumnSumToEqual(column_list=['total_debits', 'total_credits'], sum_total=0)",
      "evidence_references": ["SOURCE_CONTEXT.source_documentation"]
    },
    {
      "id": "check_nonnegative_amounts",
      "description": "Ensure that the total debits and total credits are nonnegative.",
      "gx_code": "gx.expectations.ExpectColumnValuesToBeBetween(column='total_debits', min_value=0, max_value=1000000000)",
      "evidence_references": ["SOURCE_CONTEXT.source_documentation"]
    },
    {
      "id": "check_unique_journal_ids",
      "description": "Ensure that the journal IDs are unique.",
      "gx_code": "gx.expectations.ExpectColumnValuesToBeUnique(column='journal_id')",
      "evidence_references": ["SOURCE_CONTEXT.existing_controls"]
    }
  ],
  "abstentions": [
    "check_signed_balances",
    "check_unknown_conventions",
    "check_units"
  ]
}
